begin;
create table if not exists public.deal_contract_review_rounds(id uuid primary key default gen_random_uuid(),contract_version_id uuid not null references public.deal_contract_versions(id) on delete restrict,status text not null default 'active' check(status in('active','changes_requested','unanimously_approved','superseded','cancelled')),pdf_storage_path text not null,pdf_hash text not null,expires_at timestamptz not null,created_by uuid not null references public.profiles(id) on delete restrict,created_at timestamptz not null default now(),closed_at timestamptz,unique(contract_version_id));
create table if not exists public.deal_contract_reviewers(id uuid primary key default gen_random_uuid(),round_id uuid not null references public.deal_contract_review_rounds(id) on delete cascade,participant_id uuid not null references public.deal_participants(id) on delete restrict,status text not null default 'new' check(status in('new','viewing','accepted','changes_requested')),token_hash text not null unique,token_expires_at timestamptz not null,last_accessed_at timestamptz,decided_at timestamptz,general_comment text,created_at timestamptz not null default now(),unique(round_id,participant_id));
create table if not exists public.deal_contract_annotations(id uuid primary key default gen_random_uuid(),reviewer_id uuid not null references public.deal_contract_reviewers(id) on delete cascade,page integer not null check(page>0),kind text not null check(kind in('comment','highlight','strike','freehand','arrow','circle','insertion')),x numeric not null check(x between 0 and 1),y numeric not null check(y between 0 and 1),width numeric check(width between 0 and 1),height numeric check(height between 0 and 1),points jsonb not null default '[]',comment text,status text not null default 'new' check(status in('new','in_review','accepted','partially_accepted','rejected','resolved')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists idx_contract_reviewers_round on public.deal_contract_reviewers(round_id,status);create index if not exists idx_contract_annotations_reviewer on public.deal_contract_annotations(reviewer_id,page,created_at);
alter table public.deal_contract_review_rounds enable row level security;alter table public.deal_contract_reviewers enable row level security;alter table public.deal_contract_annotations enable row level security;revoke all on public.deal_contract_review_rounds,public.deal_contract_reviewers,public.deal_contract_annotations from public,anon;grant select on public.deal_contract_review_rounds,public.deal_contract_reviewers,public.deal_contract_annotations to authenticated;
create policy "owners read review rounds" on public.deal_contract_review_rounds for select to authenticated using(exists(select 1 from public.deal_contract_versions v join public.deal_contracts c on c.id=v.contract_id where v.id=contract_version_id and public.owns_deal_dossier(c.dossier_id)) and public.has_satisfied_mfa());
create policy "owners read reviewers" on public.deal_contract_reviewers for select to authenticated using(exists(select 1 from public.deal_contract_review_rounds rr join public.deal_contract_versions v on v.id=rr.contract_version_id join public.deal_contracts c on c.id=v.contract_id where rr.id=round_id and public.owns_deal_dossier(c.dossier_id)) and public.has_satisfied_mfa());
create policy "owners manage annotations" on public.deal_contract_annotations for all to authenticated using(exists(select 1 from public.deal_contract_reviewers rv join public.deal_contract_review_rounds rr on rr.id=rv.round_id join public.deal_contract_versions v on v.id=rr.contract_version_id join public.deal_contracts c on c.id=v.contract_id where rv.id=reviewer_id and public.owns_deal_dossier(c.dossier_id)) and public.has_satisfied_mfa());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('deal-contracts','deal-contracts',false,20971520,array['application/pdf']) on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create policy "owners read deal contracts" on storage.objects for select to authenticated using(bucket_id='deal-contracts' and public.owns_deal_dossier(((storage.foldername(name))[1])::uuid));

create or replace function public.prepare_contract_review(p_actor uuid,p_contract_version_id uuid,p_pdf_path text,p_pdf_hash text,p_valid_days integer default 10) returns jsonb language plpgsql security definer set search_path='' as $$
declare v_version public.deal_contract_versions%rowtype;v_contract public.deal_contracts%rowtype;v_round uuid;v_reviewer uuid;v_participant public.deal_participants%rowtype;v_token text;v_reviewers jsonb:='[]';
begin
 select * into v_version from public.deal_contract_versions where id=p_contract_version_id and status='ready';if not found then raise exception 'DEAL_CONTRACT_VERSION_INVALID';end if;select * into v_contract from public.deal_contracts where id=v_version.contract_id and created_by=p_actor;if not found then raise exception 'DEAL_ACCESS_DENIED';end if;
 if p_pdf_path not like v_contract.dossier_id::text||'/%' or length(p_pdf_hash)<>64 then raise exception 'DEAL_PDF_INVALID';end if;
 update public.deal_contract_review_rounds rr set status='superseded',closed_at=now() from public.deal_contract_versions ov where ov.id=rr.contract_version_id and ov.contract_id=v_contract.id and rr.status in('active','changes_requested');
 insert into public.deal_contract_review_rounds(contract_version_id,pdf_storage_path,pdf_hash,expires_at,created_by) values(v_version.id,p_pdf_path,p_pdf_hash,now()+make_interval(days=>least(greatest(p_valid_days,1),30)),p_actor) on conflict(contract_version_id) do update set pdf_storage_path=excluded.pdf_storage_path,pdf_hash=excluded.pdf_hash,expires_at=excluded.expires_at,status='active',closed_at=null returning id into v_round;
 for v_participant in select * from public.deal_participants where dossier_id=v_contract.dossier_id and status<>'inactive' and nullif(btrim(email),'') is not null loop v_token:=encode(extensions.gen_random_bytes(32),'hex');insert into public.deal_contract_reviewers(round_id,participant_id,token_hash,token_expires_at) values(v_round,v_participant.id,encode(extensions.digest(v_token,'sha256'),'hex'),now()+make_interval(days=>least(greatest(p_valid_days,1),30))) on conflict(round_id,participant_id) do update set status='new',token_hash=excluded.token_hash,token_expires_at=excluded.token_expires_at,last_accessed_at=null,decided_at=null,general_comment=null returning id into v_reviewer;v_reviewers:=v_reviewers||jsonb_build_array(jsonb_build_object('reviewer_id',v_reviewer,'participant_id',v_participant.id,'name',v_participant.name,'email',v_participant.email,'token',v_token));end loop;
 if jsonb_array_length(v_reviewers)=0 then raise exception 'DEAL_REVIEWERS_REQUIRED';end if;update public.deal_contracts set status='in_review',updated_at=now() where id=v_contract.id;return jsonb_build_object('round_id',v_round,'dossier_id',v_contract.dossier_id,'version',v_version.version,'reviewers',v_reviewers);
end;$$;revoke all on function public.prepare_contract_review(uuid,uuid,text,text,integer) from public,anon,authenticated;grant execute on function public.prepare_contract_review(uuid,uuid,text,text,integer) to service_role;

create or replace function public.get_public_contract_review(p_token text) returns jsonb language plpgsql security definer set search_path='' as $$
declare v_r public.deal_contract_reviewers%rowtype;v_round public.deal_contract_review_rounds%rowtype;v_result jsonb;
begin if length(coalesce(p_token,''))<>64 then raise exception 'DEAL_LINK_INVALID';end if;select * into v_r from public.deal_contract_reviewers where token_hash=encode(extensions.digest(p_token,'sha256'),'hex') for update;select * into v_round from public.deal_contract_review_rounds where id=v_r.round_id;if not found or v_r.token_expires_at<=now() or v_round.status not in('active','changes_requested') then raise exception 'DEAL_LINK_INVALID';end if;update public.deal_contract_reviewers set status=case when status='new' then 'viewing' else status end,last_accessed_at=now() where id=v_r.id;
 select jsonb_build_object('reviewer_id',v_r.id,'status',v_r.status,'expires_at',v_r.token_expires_at,'pdf_path',v_round.pdf_storage_path,'pdf_hash',v_round.pdf_hash,'participant',jsonb_build_object('name',p.name,'role',p.role),'version',cv.version,'property_title',cv.content->'snapshot'->'content'->'dossier'->'inherited_snapshot'->'property'->>'title','annotations',coalesce((select jsonb_agg(to_jsonb(a) order by a.created_at) from public.deal_contract_annotations a where a.reviewer_id=v_r.id),'[]')) into v_result from public.deal_participants p join public.deal_contract_versions cv on cv.id=v_round.contract_version_id where p.id=v_r.participant_id;return v_result;end;$$;revoke all on function public.get_public_contract_review(text) from public,anon,authenticated;grant execute on function public.get_public_contract_review(text) to service_role;

create or replace function public.submit_public_contract_review(p_token text,p_decision text,p_comment text,p_annotations jsonb default '[]') returns jsonb language plpgsql security definer set search_path='' as $$
declare v_r public.deal_contract_reviewers%rowtype;v_round public.deal_contract_review_rounds%rowtype;v_a jsonb;v_all integer;v_accepted integer;
begin if p_decision not in('accept','request_changes') or (p_decision='request_changes' and char_length(btrim(coalesce(p_comment,'')))<3) then raise exception 'DEAL_REVIEW_INVALID';end if;select * into v_r from public.deal_contract_reviewers where token_hash=encode(extensions.digest(p_token,'sha256'),'hex') for update;select * into v_round from public.deal_contract_review_rounds where id=v_r.round_id for update;if not found or v_r.token_expires_at<=now() or v_round.status not in('active','changes_requested') then raise exception 'DEAL_LINK_INVALID';end if;delete from public.deal_contract_annotations where reviewer_id=v_r.id;for v_a in select * from jsonb_array_elements(coalesce(p_annotations,'[]')) loop insert into public.deal_contract_annotations(reviewer_id,page,kind,x,y,width,height,points,comment) values(v_r.id,greatest(1,coalesce((v_a->>'page')::integer,1)),v_a->>'kind',least(greatest(coalesce((v_a->>'x')::numeric,0),0),1),least(greatest(coalesce((v_a->>'y')::numeric,0),0),1),nullif(v_a->>'width','')::numeric,nullif(v_a->>'height','')::numeric,coalesce(v_a->'points','[]'),nullif(btrim(v_a->>'comment'),''));end loop;update public.deal_contract_reviewers set status=case when p_decision='accept' then 'accepted' else 'changes_requested' end,general_comment=nullif(btrim(p_comment),''),decided_at=now() where id=v_r.id;select count(*),count(*)filter(where status='accepted') into v_all,v_accepted from public.deal_contract_reviewers where round_id=v_round.id;update public.deal_contract_review_rounds set status=case when p_decision='request_changes' then 'changes_requested' when v_all=v_accepted then 'unanimously_approved' else 'active' end,closed_at=case when v_all=v_accepted then now() else null end where id=v_round.id;if v_all=v_accepted then update public.deal_contract_versions set status='final' where id=v_round.contract_version_id;update public.deal_contracts c set status='approved',updated_at=now() from public.deal_contract_versions v where v.id=v_round.contract_version_id and c.id=v.contract_id;end if;return jsonb_build_object('accepted',v_accepted,'total',v_all,'unanimous',v_all=v_accepted);end;$$;revoke all on function public.submit_public_contract_review(text,text,text,jsonb) from public,anon,authenticated;grant execute on function public.submit_public_contract_review(text,text,text,jsonb) to service_role;
notify pgrst,'reload schema';commit;
